import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import * as processIdentity from '../../../platform/process/process-identity.js';
import {
  type RuntimeAction,
  type WorkflowRun,
  createRuntime,
  createMemoryRuntimeStore,
  hashRuntimeValue,
  type RuntimeValue,
} from '../../../domains/engine/runtime.js';
import {
  createNativeSdkCheckExecution,
  reconcileNativeSdkExecutionStops,
  acknowledgeNativeSdkCheckStopped,
  terminateNativeSdkCheckExecutions,
  inspectNativeSdkCheckExecutions,
} from '../../../domains/comet-native/native-sdk-check-execution.js';

import { inspectNativeSdkCancellation } from '../../../domains/comet-native/native-sdk-cancellation.js';
import { recoverNativeSdkChecks } from '../../../domains/comet-native/native-sdk-checks.js';

const originalPlatform = Object.getOwnPropertyDescriptor(process, 'platform')!;
let root: string;
beforeEach(async () => {
  root = await fs.mkdtemp(path.join(os.tmpdir(), 'native-check-termination-'));
  vi.spyOn(processIdentity, 'readProcessIdentity').mockResolvedValue('original-identity');
  vi.spyOn(processIdentity, 'inspectProcessLiveness').mockResolvedValue('dead');
  vi.spyOn(processIdentity, 'inspectProcessTreeLiveness').mockResolvedValue('dead');
});
afterEach(async () => {
  Object.defineProperty(process, 'platform', originalPlatform);
  vi.restoreAllMocks();
  await fs.rm(root, { recursive: true, force: true });
});

async function registration(phase: 'running' | 'interrupted' | 'completed', modern = false) {
  const action = {
    id: 'check-action',
    runId: 'check-run',
    attempt: 1,
    inputHash: 'original-input',
    type: 'call_tool',
    ref: 'native-required-checks',
    status: 'unknown',
    claim: { token: 'original-claim', executorId: 'comet-native-checks' },
  } as RuntimeAction;
  const run = {
    runId: 'check-run',
    workflow: { id: 'comet-native', version: '1', hash: 'a'.repeat(64) },
    actions: [action],
  } as WorkflowRun;
  const registered = await createNativeSdkCheckExecution({
    projectRoot: root,
    run,
    action,
    candidateId: 'original-candidate',
    plansHash: 'original-plans',
  });
  await registered.register('check-1', modern ? instance : 123456);
  registered.execution.phase = phase;
  await registered.save();
  return { run, action, registered };
}

it('reuses a confirmed stop only while the complete execution record still matches', async () => {
  const { run, action, registered } = await registration('completed');
  action.status = 'succeeded';
  action.executionStop = {
    actionId: action.id,
    attempt: action.attempt,
    inputHash: action.inputHash,
    claimToken: action.claim!.token,
    evidence: `Runtime 已确认原受管执行停止；执行记录摘要 ${hashRuntimeValue(registered.execution as unknown as RuntimeValue)}`,
  } as NonNullable<RuntimeAction['executionStop']>;
  vi.mocked(processIdentity.inspectProcessLiveness).mockClear();
  vi.mocked(processIdentity.inspectProcessTreeLiveness).mockClear();
  expect(
    (await inspectNativeSdkCheckExecutions({ projectRoot: root, run, includeSettled: true }))[0],
  ).toMatchObject({ quiescent: true, recoveryRequired: false });
  expect(processIdentity.inspectProcessLiveness).not.toHaveBeenCalled();
  expect(processIdentity.inspectProcessTreeLiveness).not.toHaveBeenCalled();
  registered.execution.checkId = 'changed-execution';
  await registered.save();
  await inspectNativeSdkCheckExecutions({ projectRoot: root, run, includeSettled: true });
  expect(processIdentity.inspectProcessLiveness).toHaveBeenCalled();
});

it.each(['running', 'interrupted', 'completed'] as const)(
  'keeps a Windows %s check blocked when both owner and supervisor exited without tree evidence',
  async (phase) => {
    const { run } = await registration(phase);
    Object.defineProperty(process, 'platform', { ...originalPlatform, value: 'win32' });
    const [inspection] = await inspectNativeSdkCheckExecutions({ projectRoot: root, run });
    expect(inspection).toMatchObject({
      owner: 'dead',
      process: 'dead',
      quiescent: false,
      recoveryRequired: true,
    });
