        projectRoot: directory,
        runtimeDir: path.join(directory, 'runtime'),
        operationId: 'register',
        plan: {
          id: 'check',
          name: 'check',
          executable: process.execPath,
          argv: ['-e', "require('node:fs').writeFileSync(process.argv[1], 'bad')", marker],
          cwdRef: '.',
          timeoutMs: 150,
          repeatable: false,
        },
        onSpawn: async () => new Promise(() => {}),
      }),
    ).rejects.toThrow(/登记.*时限/u);
    expect(Date.now() - started).toBeLessThan(1500);
    expect(await exists(marker)).toBe(false);
  });

  it('kills background descendants before reporting their parent command complete', async () => {
    const directory = await root();
    const marker = path.join(directory, 'background');
    const grandchild =
      "setTimeout(() => require('node:fs').writeFileSync(process.argv[1], 'bad'), 500)";
    const result = await executeNativeCheck({
      projectRoot: directory,
      runtimeDir: path.join(directory, 'runtime'),
      operationId: 'background',
      plan: {
        id: 'check',
        name: 'check',
        executable: process.execPath,
        argv: [
          '-e',
          `require('node:child_process').spawn(process.execPath, ['-e', ${JSON.stringify(grandchild)}, process.argv[1]], { stdio: 'ignore' }).unref()`,
          marker,
        ],
        cwdRef: '.',
        timeoutMs: 2000,
        repeatable: false,
      },
    });
    expect(result.status).toBe('passed');
    await sleep(650);
    expect(await exists(marker)).toBe(false);
  });

  it('does not replay a check after its supervisor is killed before completion', async () => {
    const directory = await root();
    const { runtime, run, action } = await claimedRun();
    const registration = await createNativeSdkCheckExecution({
      projectRoot: directory,
      run,
      action,
      candidateId: 'candidate',
      plansHash: 'plans',
    });
    const started = path.join(directory, 'started');
    const supervisor = spawnOwnedCommand(
      process.execPath,
      [
        '-e',
        `require('node:fs').writeFileSync(${JSON.stringify(started)}, String(process.pid)); setTimeout(() => process.exit(0), 25000)`,
      ],
      { cwd: directory, timeoutMs: 10000 },
    );
    processes.push(supervisor.child);
    await registration.register('check', supervisor.child.pid!);
    supervisor.start();
    await waitForCondition(() => exists(started), 'check did not start');
    supervisor.child.kill('SIGKILL');
    await waitForProcessExit(supervisor.child);
    const checkPid = Number(await fs.readFile(started, 'utf8'));
    const checkIdentity = await readProcessIdentity(checkPid);
    try {
      if (process.platform !== 'win32') expect(checkIdentity).not.toBeNull();
      const status = (await inspectNativeSdkCheckExecutions({ projectRoot: directory, run }))[0];
      expect(status.processBoundary).toBe(
        process.platform === 'win32' ? 'supervisor-process' : 'process-group',
      );
      expect(status.process).toBe(process.platform === 'win32' ? 'dead' : 'unknown');
      if (process.platform !== 'win32')
        expect(await readProcessIdentity(checkPid)).toBe(checkIdentity);
      expect(status.quiescent).toBe(false);
      await expect(
        createNativeSdkCheckExecution({
          projectRoot: directory,
          run,
          action,
          candidateId: 'candidate',
          plansHash: 'plans',
        }),
      ).rejects.toMatchObject({ code: 'EEXIST' });
      // 进程仍活着时不得依赖原监管器 PID 消失释放工作区。
      expect((await runtime.inspect(run.runId)).actions[0].attempt).toBe(1);
    } finally {
      if (checkIdentity && (await readProcessIdentity(checkPid)) === checkIdentity) {
        try {
          process.kill(checkPid, 'SIGKILL');
        } catch {
          /* 原检查进程已退出 */
        }
      }
    }
    await waitForCondition(
      async () =>
        (await inspectProcessTreeLiveness(
          supervisor.child.pid!,
          registration.execution.child!.identity,
        )) === 'dead',
      'process group did not stop',
    );
  });

  it('records owner death as unknown while preserving claim and refuses overwrite across attempts', async () => {
    const directory = await root();
    const { runtime, run, action } = await claimedRun();
    const registration = await createNativeSdkCheckExecution({
      projectRoot: directory,
      run,
      action,
      candidateId: 'candidate',
      plansHash: 'plans',
    });
    const owner = spawn(process.execPath, ['-e', 'setTimeout(() => {}, 10000)'], {
      stdio: 'ignore',
    });
    processes.push(owner);
    registration.execution.owner = {
      pid: owner.pid!,
      identity: (await readProcessIdentity(owner.pid!)) ?? undefined,
    };
    await registration.save();
    owner.kill('SIGKILL');
    await waitForProcessExit(owner);
    const recovered = await recoverNativeSdkChecks(directory, run, runtime);
    expect(recovered.actions[0]).toMatchObject({
      status: 'unknown',
      claim: action.claim,
      attempt: 1,
    });
    const again = await recoverNativeSdkChecks(directory, recovered, runtime);
    expect(again.revision).toBe(recovered.revision);
    await expect(
      runtime.retry({ runId: run.runId, actionId: action.id, attempt: 1 }),
    ).rejects.toMatchObject({ code: 'RECONCILIATION_REQUIRED' });
    const retried = await runtime.retry({
      runId: run.runId,
      actionId: action.id,
      attempt: 1,
      reconciliation: { resolution: 'not-executed', evidence: 'unsupported assertion' },
    });
    const next = retried.actions[0];
    const claimed = await runtime.claim({
      runId: run.runId,
      actionId: next.id,
      attempt: next.attempt,
      inputHash: next.inputHash,
      executorId: 'comet-native-checks',
      claimToken: 'another-claim',
    });
    await expect(
      createNativeSdkCheckExecution({
        projectRoot: directory,
        run: claimed,
        action: claimed.actions[0],
        candidateId: 'candidate',
        plansHash: 'plans',
      }),
    ).rejects.toMatchObject({ code: 'EEXIST' });
  });

  it('persists cancellation before a delayed executor has registered so it cannot launch', async () => {
    const directory = await root();
    const { run, action } = await claimedRun();
    expect(
      (await terminateNativeSdkCheckExecutions({ projectRoot: directory, run }))[0].phase,
    ).toBe('missing');
    const registration = await createNativeSdkCheckExecution({
      projectRoot: directory,
      run,
      action,
      candidateId: 'candidate',
      plansHash: 'plans',
    });
    await expect(registration.assertNotStopped()).rejects.toThrow(/取消/u);
    await expect(registration.register('delayed', process.pid)).rejects.toThrow(/取消/u);
    expect(registration.execution.child).toBeUndefined();
  });

  it('does not treat a reused process PID as the original child instance', async () => {
    const directory = await root();
    const { run, action } = await claimedRun();
    const registration = await createNativeSdkCheckExecution({
      projectRoot: directory,
      run,
      action,
      candidateId: 'candidate',
      plansHash: 'plans',
    });
    registration.execution.child = { pid: process.pid, identity: 'linux:prior-boot:1' };
    registration.execution.phase = 'completed';
    await registration.save();
    const [status] = await inspectNativeSdkCheckExecutions({ projectRoot: directory, run });
    expect(status.process).toBe('dead');
    // PID 身份已不匹配只证明原组长消失；Windows 旧登记仍缺整树停止收据。
    expect(status.quiescent).toBe(process.platform !== 'win32');
  });
});

import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { executeNativeCheck } from '../../../domains/comet-native/native-check-executor.js';
import * as ownedCommand from '../../../platform/process/owned-command.js';
import * as processIdentity from '../../../platform/process/process-identity.js';

const roots: string[] = [];
afterEach(async () => {
  vi.restoreAllMocks();
  for (const root of roots.splice(0)) await fs.rm(root, { recursive: true, force: true });
});
async function setup() {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-check-registration-'));
  roots.push(root);
  return { projectRoot: root, runtimeDir: path.join(root, 'runtime'), operationId: 'registration' };
}

describe('Native check process registration', () => {
  it('does not invoke registration after cancellation during identity lookup', async () => {
    let releaseIdentity!: () => void;
    let identityStarted!: () => void;
    const started = new Promise<void>((resolve) => {
      identityStarted = resolve;
    });
    const released = new Promise<void>((resolve) => {
      releaseIdentity = resolve;
    });
    vi.spyOn(processIdentity, 'readProcessIdentity').mockImplementation(async () => {
      identityStarted();
      await released;
      return null;
    });
    const onSpawn = vi.fn(async () => {});
    const pending = executeNativeCheck({
      ...(await setup()),
      plan: {
        id: 'cancelled',
        name: 'Cancelled registration',
        executable: process.execPath,
        argv: ['-e', 'setInterval(() => {}, 1000)'],
        cwdRef: '.',
        timeoutMs: 1000,
        repeatable: true,
      },
      onSpawn,
    });
    try {
      await started;
      await expect(pending).rejects.toThrow('检查进程登记超过执行时限');
    } finally {
      releaseIdentity();
    }
    await new Promise<void>((resolve) => setImmediate(resolve));
    expect(onSpawn).not.toHaveBeenCalled();
  });
  it('waits for registration even if the check has already exited', async () => {
    let registered = false;
    const result = await executeNativeCheck({
      ...(await setup()),
      plan: {
        id: 'fast',
        name: 'Fast check',
        executable: process.execPath,
        argv: ['-e', 'process.exit(0)'],
        cwdRef: '.',
        timeoutMs: 5000,
        repeatable: true,
      },
      onSpawn: async ({ pid }) => {
        expect(pid).toBeGreaterThan(0);
        await new Promise((resolve) => setTimeout(resolve, 200));
        registered = true;
      },
    });
    expect(registered).toBe(true);
    expect(result.status).toBe('passed');
  });

  it('terminates the check and preserves a registration failure before returning', async () => {
    let pid = 0;
    await expect(
      executeNativeCheck({
        ...(await setup()),
        plan: {
          id: 'slow',
          name: 'Slow check',
          executable: process.execPath,
          argv: ['-e', 'setInterval(() => {}, 1000)'],
          cwdRef: '.',
          timeoutMs: 5000,
          repeatable: true,
        },
        onSpawn: async (child) => {
          pid = child.pid;
          throw new Error('registration failed');
        },
      }),
    ).rejects.toThrow('registration failed');
    expect(pid).toBeGreaterThan(0);
    expect(() => process.kill(pid, 0)).toThrow();
  });

  it('rejects an unavailable log before spawning or registering the check', async () => {
    const options = await setup();
    const directory = path.join(options.runtimeDir, 'logs', 'checks');
    await fs.mkdir(directory, { recursive: true });
    await fs.writeFile(path.join(directory, 'registration-slow.log'), 'existing log');
    const spawn = vi.spyOn(ownedCommand, 'spawnOwnedCommand');
    const onSpawn = vi.fn(async () => {});
    await expect(
      executeNativeCheck({
        ...options,
        plan: {
          id: 'slow',
          name: 'Slow check',
          executable: process.execPath,
          argv: ['-e', 'setInterval(() => {}, 1000)'],
          cwdRef: '.',
          timeoutMs: 5000,
          repeatable: true,
        },
        onSpawn,
      }),
    ).rejects.toMatchObject({ code: 'EEXIST' });
    expect(spawn).not.toHaveBeenCalled();
    expect(onSpawn).not.toHaveBeenCalled();
    expect(await fs.readFile(path.join(directory, 'registration-slow.log'), 'utf8')).toBe(
      'existing log',
    );
  });
});

import { createHash } from 'node:crypto';
