    await expect(
      ensureWorkspaceRuntimeMigrationFence(copied, isolated, { projectRoot: clone }),
    ).rejects.toThrow('其他工作区或目标');
    await ensureWorkspaceRuntimeMigrationFence(copied, isolated, {
      projectRoot: clone,
      ignoreForeignWorkspaceFence: true,
