    const buildArgv = f.command('upgraded-build');
    const verifyArgv = f.command('upgraded-verify');
    await f.put(
      '.comet/check-policy.json',
      JSON.stringify({
        version: 2,
        commands: [buildArgv, verifyArgv].map((argv) => ({
          argv,
          cwd: '.',
          files: ['source.js'],
        })),
      }),
    );
    const proposal = await f.cli(
