    ).not.toBe(0);
    await expect(fs.readFile(f.checkCount, 'utf8')).rejects.toMatchObject({ code: 'ENOENT' });
    // 隔离夹具模拟用户批准；首次检查不能代替升级、设计和实施配置的批准。
    await f.cli(
