    await f.cli(
      'check',
      'run',
      'example',
      'verify',
      '--report',
      f.reportRef,
      '--local',
      '--',
      ...verifyArgv,
    );
    expect((await f.inspect()).state).toMatchObject({ phase: 'verify', verifyResult: 'pending' });
    await f.put(f.reportRef, '# Verification\nThe upgraded full workflow passed acceptance.\n');
    await f.cli(
      'guard',
      'example',
      'verify',
      '--report',
      f.reportRef,
      '--apply',
      '--local',
      '--',
      ...verifyArgv,
    );
