    )!;
    await expect(
      runtime.recordEvidence({
        runId: run.runId,
        expectedRevision: checked.revision,
        evidenceId: wait.id,
        kind: wait.kind,
        ref: oldOutput.receiptRef,
        contentHash: oldCheck.inputHash,
        submissionId: randomUUID(),
