      expect(checked.evidenceWaits?.at(-1)?.status).toBe('pending');
      if (cold) {
        await fs.rename(
          resolveWorkspaceRuntimeRootSync(f.projectRoot),
          path.join(path.dirname(f.projectRoot), 'committed-check-runtime'),
        );
        await f.cli('state', 'next', 'example');
