      execution: { stage: 'checking', actor: 'runtime', status: 'completed' },
      checks: [],
    });
    await expect(
      executeNativePortableCheckPlan({ paths, name: 'change', plans: [] }),
    ).resolves.toMatchObject({ disposition: 'reused', checks: [] });
