import { withNativeMutationLock } from '../../../domains/comet-native/native-mutation-lock.js';

const roots: string[] = [];
afterEach(async () => {
  vi.restoreAllMocks();
  for (const root of roots.splice(0)) await fs.rm(root, { recursive: true, force: true });
});
const git = (cwd: string, ...args: string[]) =>
  execFileSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

async function setup(secondChild = false) {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-supervisor-process-'));
  roots.push(root);
  git(root, 'init', '-b', 'main');
  git(root, 'config', 'user.email', 'test@example.test');
  git(root, 'config', 'user.name', 'Test');
  await writeProjectConfig(root, defaultProjectConfig('docs', 'en'));
  await fs.writeFile(
    path.join(root, '.gitignore'),
    '.comet/runtime/\n.comet/current-change.json\n.worktrees/\n',
  );
  git(root, 'add', '.');
  git(root, 'commit', '-m', 'seed');
  const paths = await nativeProjectPaths(root, 'docs');
  await ensureNativeDirectories(paths);
  await createNativePortableChange({
    paths,
    name: 'change',
    language: 'en',
    workspaceBinding: { isolation: 'current', changeBranch: 'main', targetBranch: 'main' },
  });
  const changeDir = nativePortableChangeDir(paths, 'change');
  await fs.writeFile(
    path.join(changeDir, 'brief.md'),
    '# Acceptance examples\n- The behavior works.\n' +
      (secondChild ? '- Another behavior works.\n' : ''),
  );
  await fs.writeFile(
    path.join(changeDir, 'children.yaml'),
    'schema: comet.native.children.v2\nacceptance_index:\n  A1:\n    source: brief.md\n    text: The behavior works.\n' +
      (secondChild ? '  A2:\n    source: brief.md\n    text: Another behavior works.\n' : '') +
      'children:\n  - name: core\n    depends_on: []\n    covers: [A1]\n' +
      (secondChild ? '  - name: auxiliary\n    depends_on: []\n    covers: [A2]\n' : ''),
  );
  const coordination = secondChild ? { coordinationMode: 'multi-session' as const } : {};
  await prepareNativePortableShapeConfirmation({ paths, name: 'change', ...coordination });
  await confirmNativePortableShape({ paths, name: 'change', ...coordination });
  const builders = (
    await dispatchNativeSupervisorReadyTasks({ paths, parent: 'change', maxParallel: 2 })
  ).tasks;
  const verifierRunIds: Record<string, string> = {};
  for (const builder of builders) {
    await fs.writeFile(path.join(builder.projectRoot, `${builder.child}.txt`), 'implemented');
    git(builder.projectRoot, 'add', `${builder.child}.txt`);
    git(builder.projectRoot, 'commit', '-m', 'implement');
    const result = await applyNativeRunnerInput({
      paths,
      name: 'change',
      maxVerifyFailures: 5,
      input: {
        kind: 'supervisor-builder-result',
        child: builder.child,
        runId: builder.runId,
        candidateCommit: git(builder.projectRoot, 'rev-parse', 'HEAD'),
      },
    });
    verifierRunIds[builder.child] = result.supervisorTask!.runId;
  }
  const marker = path.join(root, 'starts.txt');
  const release = path.join(root, 'release');
  const code =
    "require('fs').appendFileSync(process.argv[1],String(process.pid)+'\\n');setInterval(()=>{if(require('fs').existsSync(process.argv[2]))process.exit(0)},25)";
  const options = {
    paths,
    parent: 'change',
    child: 'core',
    runId: verifierRunIds.core,
    plans: [
      {
        id: 'slow',
        name: 'Slow check',
        executable: process.execPath,
        argv: ['-e', code, marker, release],
        cwdRef: '.',
        timeoutMs: 10000,
        repeatable: true,
      },
    ],
    materials: [],
  };
  return {
    root,
    paths,
    marker,
    release,
    options,
    secondaryOptions: { ...options, child: 'auxiliary', runId: verifierRunIds.auxiliary },
  };
}

describe('Supervisor check process recovery', () => {
  it('preserves unconfirmed process termination and blocks owner-dead recovery', async () => {
    const { paths, options, secondaryOptions } = await setup(true);
    const failure = new checkExecutor.NativeCheckTerminationUnconfirmedError();
    const execute = vi
      .spyOn(checkExecutor, 'executeNativeCheck')
      .mockImplementation(async ({ onSpawn }) => {
        await onSpawn?.({ pid: 2147483000, signal: new AbortController().signal });
        throw failure;
      });
    await expect(executeNativeSupervisorChecks(options)).rejects.toBe(failure);
    await expect(executeNativeSupervisorChecks(secondaryOptions)).rejects.toBe(failure);
    const preserved = (await readNativeSupervisorState(paths, 'change'))!;
    const execution = preserved.children[0].task!.checkExecution!;
    expect(execution).toMatchObject({
      status: 'running',
      activeProcess: { status: 'running', checkId: 'slow', pid: 2147483000 },
      checkStates: [{ id: 'slow', status: 'running', executionCount: 1 }],
    });
    await expect(
      executeNativeSupervisorChecks({ ...options, retryCheckIds: ['slow'] }),
    ).resolves.toMatchObject({ status: 'running', operationId: execution.operationId });

    execution.ownerPid = 2147483001;
    preserved.children[1].task!.checkExecution!.ownerPid = 2147483001;
    await writeNativeSupervisorState(paths, preserved);
    vi.spyOn(checkExecutor, 'inspectNativeCheckProcessTreeLiveness').mockResolvedValue('unknown');
    await expect(executeNativeSupervisorChecks(options)).resolves.toMatchObject({
      status: 'running',
      operationId: execution.operationId,
    });
    expect(
      (await readNativeSupervisorState(paths, 'change'))!.children[0].task!.checkExecution,
    ).toEqual(execution);
    expect(execute).toHaveBeenCalledTimes(2);

    const target = (await inspectNativeCheckStopEvidenceTargets(paths, 'change')).find(
      ({ child }) => child === 'core',
    )!;
    expect(target.canConfirm).toBe(true);
    const proofFile = path.join(paths.workspaceRuntimeRoot, 'supervisor-stopped.json');
    await fs.writeFile(
      proofFile,
      JSON.stringify([
        {
          ...target.confirmation,
          evidence:
            'Confirmed this original child check and all descendants stopped using the host process inventory.',
        },
      ]),
    );
    const command = () =>
      nativeDoctorCommand(
        ['change', '--repair', '--confirmed', '--stopped-actions', proofFile],
        paths.projectRoot,
      );
    const originalWrite = atomicFile.atomicWriteJson;
    const failApplied = vi
      .spyOn(atomicFile, 'atomicWriteJson')
      .mockImplementation(async (file, value, settings) => {
        if (
          (value as { schema?: string; applied?: boolean }).schema ===
            'comet.native.check-stop-evidence.v1' &&
          (value as { applied?: boolean }).applied
        )
          throw new Error('applied write failed');
        return originalWrite(file, value, settings);
      });
    await expect(command()).rejects.toThrow('applied write failed');
    failApplied.mockRestore();
    const interrupted = (await readNativeSupervisorState(paths, 'change'))!;
    expect(interrupted.stateVersion).toBe(preserved.stateVersion + 1);
    expect(interrupted.children[0].task!.checkExecution).toMatchObject({
      status: 'interrupted',
      operationId: execution.operationId,
      activeProcess: null,
      checkStates: [{ id: 'slow', status: 'interrupted', executionCount: 1 }],
    });
    expect(interrupted.children[1].task!.checkExecution).toEqual(
      preserved.children[1].task!.checkExecution,
    );
    await expect(command()).resolves.toMatchObject({
      exitCode: 65,
      data: {
        healthy: false,
        repaired: false,
        stoppedChecks: { alreadyApplied: true },
        findings: [{ code: 'supervisor-check-execution-stuck', child: 'auxiliary' }],
      },
    });
    await expect(command()).resolves.toMatchObject({
      exitCode: 65,
      data: { healthy: false, repaired: false },
    });
    expect(await readNativeSupervisorState(paths, 'change')).toEqual(interrupted);
    expect(execute).toHaveBeenCalledTimes(2);
  });

  it('does not start another check while the registered process outlives its recorded owner', async () => {
    const { paths, marker, release, options } = await setup();
    const running = executeNativeSupervisorChecks(options);
    try {
      let registered = false;
      for (let index = 0; index < 100; index += 1) {
        const state = await readNativeSupervisorState(paths, 'change');
        if (state!.children[0].task!.checkExecution?.activeProcess?.status === 'running') {
          registered = true;
          break;
        }
        await delay(50);
      }
      expect(registered).toBe(true);
      const stoppedPid = Number(
        execFileSync(process.execPath, ['-p', 'process.pid'], { encoding: 'utf8' }).trim(),
      );
      expect(() => process.kill(stoppedPid, 0)).toThrow();
      await withNativeMutationLock(paths, 'simulate exited Supervisor owner', async () => {
        const state = await readNativeSupervisorState(paths, 'change');
        state!.children[0].task!.checkExecution!.ownerPid = stoppedPid;
        await writeNativeSupervisorState(paths, state!);
      });
      const resumed = await executeNativeSupervisorChecks(options);
      expect(resumed.status).toBe('running');
      expect((await fs.readFile(marker, 'utf8')).trim().split(/\r?\n/u)).toHaveLength(1);
    } finally {
      await fs.writeFile(release, 'done');
      await running;
    }
    const completed = await executeNativeSupervisorChecks(options);
    expect(completed.status).toBe('completed');
    // A stopped owner and a finished child provide a safe boundary for a fresh attempt.
    await withNativeMutationLock(paths, 'simulate lost completion write', async () => {
      const state = await readNativeSupervisorState(paths, 'change');
      state!.children[0].task!.checkExecution!.status = 'running';
      await writeNativeSupervisorState(paths, state!);
    });
    const recovered = await executeNativeSupervisorChecks(options);
    expect(recovered.status).toBe('completed');
    expect(recovered.operationId).toBe(completed.operationId);
  }, 60000);

  it('reconciles a complete check receipt even when the former owner process is alive', async () => {
    const { paths, marker, release, options } = await setup();
    await fs.writeFile(release, 'done');
    const completed = await executeNativeSupervisorChecks(options);
    expect(completed.status).toBe('completed');
    await withNativeMutationLock(paths, 'simulate lost completion status', async () => {
      const state = await readNativeSupervisorState(paths, 'change');
      state!.children[0].task!.checkExecution!.status = 'running';
      await writeNativeSupervisorState(paths, state!);
    });

    const recovered = await executeNativeSupervisorChecks(options);
    expect(recovered.status).toBe('completed');
    expect(recovered.operationId).toBe(completed.operationId);
    expect((await fs.readFile(marker, 'utf8')).trim().split(/\r?\n/u)).toHaveLength(1);
  }, 60000);

  it('does not reuse a completed receipt for changed inputs after the former owner exits', async () => {
    const { paths, marker, release, options } = await setup();
    await fs.writeFile(release, 'done');
    const completed = await executeNativeSupervisorChecks(options);
    expect(completed.status).toBe('completed');
    const stoppedPid = Number(
      execFileSync(process.execPath, ['-p', 'process.pid'], { encoding: 'utf8' }).trim(),
    );
    await withNativeMutationLock(
      paths,
      'simulate lost completion status and exited owner',
      async () => {
        const state = await readNativeSupervisorState(paths, 'change');
        const execution = state!.children[0].task!.checkExecution!;
        execution.status = 'running';
        execution.ownerPid = stoppedPid;
        await writeNativeSupervisorState(paths, state!);
      },
    );

    const changedMarker = path.join(path.dirname(marker), 'changed-starts.txt');
    const changed = await executeNativeSupervisorChecks({
      ...options,
      plans: [
        { ...options.plans[0], argv: ['-e', options.plans[0].argv[1], changedMarker, release] },
      ],
    });
    expect(changed.status).toBe('completed');
    expect(changed.operationId).not.toBe(completed.operationId);
    expect((await fs.readFile(changedMarker, 'utf8')).trim().split(/\r?\n/u)).toHaveLength(1);
  }, 60000);

  it('does not replay an unregistered process and provides a candidate-preserving recovery route', async () => {
    const { paths, release, options } = await setup();
    await fs.writeFile(release, 'done');
    await executeNativeSupervisorChecks(options);
    const stoppedPid = Number(
      execFileSync(process.execPath, ['-p', 'process.pid'], { encoding: 'utf8' }).trim(),
    );
    expect(() => process.kill(stoppedPid, 0)).toThrow();
    await withNativeMutationLock(
      paths,
      'simulate interruption during process registration',
      async () => {
        const state = await readNativeSupervisorState(paths, 'change');
        const execution = state!.children[0].task!.checkExecution!;
        execution.status = 'running';
        execution.ownerPid = stoppedPid;
        execution.activeProcess = { status: 'starting', checkId: 'slow' };
        await writeNativeSupervisorState(paths, state!);
      },
    );
    await expect(executeNativeSupervisorChecks(options)).rejects.toThrow('supervisor-cancel');
    const before = await readNativeSupervisorState(paths, 'change');
    const cancelled = await applyNativeRunnerInput({
      paths,
      name: 'change',
      maxVerifyFailures: 5,
      input: {
        kind: 'supervisor-cancel',
        child: 'core',
        runId: options.runId,
        reason: 'Confirmed original check exited',
      },
    });
    expect(cancelled.supervisorState!.children[0].candidateCommit).toBe(
      before!.children[0].candidateCommit,
    );
    expect(cancelled.supervisorState!.children[0].status).toBe('needs-reverify');
  }, 60000);

  it('requires explicit retry for interrupted checks and preserves passed checks', async () => {
    const { paths, release, options } = await setup();
    const plans = [
      {
        ...options.plans[0],
        id: 'passed',
        name: 'Passed check',
        argv: ['-e', 'process.exit(0)'],
      },
      {
        ...options.plans[0],
        id: 'interrupted',
        name: 'Interrupted check',
        timeoutMs: 5000,
        argv: [
          '-e',
          "const fs=require('node:fs');const f=process.argv[1];if(fs.existsSync(f))process.exit(0);setInterval(()=>{},25)",
          release,
        ],
      },
    ];
    await expect(executeNativeSupervisorChecks({ ...options, plans })).rejects.toThrow(
      'was interrupted',
    );
    const interrupted = (await readNativeSupervisorState(paths, 'change'))!;
    const firstExecution = interrupted.children[0].task!.checkExecution!;
    expect(firstExecution.status).toBe('interrupted');
    expect(firstExecution.checkStates).toMatchObject([
      { id: 'passed', status: 'passed', executionCount: 1 },
      { id: 'interrupted', status: 'interrupted', executionCount: 1 },
    ]);

    const awaitingRetry = await executeNativeSupervisorChecks({ ...options, plans });
    expect(awaitingRetry).toMatchObject({
      status: 'interrupted',
      operationId: firstExecution.operationId,
    });
    await fs.writeFile(release, 'retry');
    const completed = await executeNativeSupervisorChecks({
      ...options,
      plans,
      retryCheckIds: ['interrupted'],
    });
    expect(completed.status).toBe('completed');
    const finalState = (await readNativeSupervisorState(paths, 'change'))!;
    expect(finalState.children[0].task!.checkExecution!.checkStates).toMatchObject([
      { id: 'passed', status: 'passed', executionCount: 1 },
      { id: 'interrupted', status: 'passed', executionCount: 2 },
    ]);
  }, 60000);
});

