const roots: string[] = [];
afterEach(async () => {
  vi.restoreAllMocks();
  for (const root of roots.splice(0)) await fs.rm(root, { recursive: true, force: true });
});
const plan = (id: string, code = 'process.exit(0)', args: string[] = []) => ({
  id,
  name: id,
  executable: process.execPath,
  argv: ['-e', code, ...args],
  cwdRef: '.',
  timeoutMs: 20000,
  repeatable: true,
});

async function verifiedSupervisor() {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-integration-execution-'));
  roots.push(root);
  const git = (cwd: string, ...args: string[]) =>
    execFileSync('git', args, { cwd, encoding: 'utf8', stdio: 'pipe' }).trim();
  git(root, 'init', '-b', 'main');
  git(root, 'config', 'user.email', 'native@example.test');
  git(root, 'config', 'user.name', 'Native Test');
  await writeProjectConfig(root, defaultProjectConfig('docs', 'en'));
  await fs.writeFile(
    path.join(root, '.gitignore'),
    '.comet/runtime/\n.comet/current-change.json\n.worktrees/\n',
  );
  git(root, 'add', '.');
  git(root, 'commit', '-m', 'seed');
  const paths = await nativeProjectPaths(root, 'docs');
  await ensureNativeDirectories(paths);
  await createNativePortableChange({
    paths,
    name: 'parent',
    language: 'en',
    workspaceBinding: { isolation: 'current', changeBranch: 'main', targetBranch: 'main' },
  });
  const changeDir = nativePortableChangeDir(paths, 'parent');
  await fs.writeFile(
    path.join(changeDir, 'brief.md'),
    '# Acceptance examples\n- The behavior works.\n',
  );
  await fs.writeFile(
    path.join(changeDir, 'children.yaml'),
    'schema: comet.native.children.v2\nchildren:\n  - name: core\n    summary: Core behavior.\n    depends_on: []\n',
  );
  await confirmNativePortableShape({ paths, name: 'parent' });
  const dispatched = await dispatchNativeSupervisorReadyTasks({
    paths,
    parent: 'parent',
    maxParallel: 1,
  });
  const builder = dispatched.tasks[0];
  await fs.writeFile(path.join(builder.projectRoot, 'feature.txt'), 'implemented');
  git(builder.projectRoot, 'add', 'feature.txt');
  git(builder.projectRoot, 'commit', '-m', 'implement');
  const result = await applyNativeRunnerInput({
    paths,
    name: 'parent',
    maxVerifyFailures: 5,
    input: {
      kind: 'supervisor-builder-result',
      child: 'core',
      runId: builder.runId,
      candidateCommit: git(builder.projectRoot, 'rev-parse', 'HEAD'),
    },
  });
  const verifier = result.supervisorTask!;
  const checked = await executeNativeSupervisorChecks({
    paths,
    parent: 'parent',
    child: 'core',
    runId: verifier.runId,
    plans: [plan('child')],
    materials: [],
  });
  await applyNativeRunnerInput({
    paths,
    name: 'parent',
    maxVerifyFailures: 5,
    input: {
      kind: 'supervisor-verifier-result',
      child: 'core',
      runId: verifier.runId,
      verdict: 'pass',
      evidence: {
        summary: 'Verified.',
        checks: ['child'],
        receiptRef: checked.receiptRef,
        acceptance: [{ id: 'child:core', result: 'passed', reason: 'Checked.' }],
      },
    },
  });
  return { root, paths, state: (await readNativeSupervisorState(paths, 'parent'))! };
}

describe('Supervisor integration check execution', () => {
  it('preserves unconfirmed process termination and blocks owner-dead recovery', async () => {
    const { paths, state } = await verifiedSupervisor();
    const failure = new checkExecutor.NativeCheckTerminationUnconfirmedError();
    const originalExecute = checkExecutor.executeNativeCheck;
    const execute = vi
      .spyOn(checkExecutor, 'executeNativeCheck')
      .mockImplementation(async (options) => {
        if (options.plan.id === 'passed') return originalExecute(options);
        await options.onSpawn?.({ pid: 2147483000, signal: new AbortController().signal });
        throw failure;
      });
    const options = {
      paths,
      state,
      name: 'core',
      checks: [],
      checkPlans: [plan('passed'), plan('pending')],
    };
    await expect(integrateNativeSupervisorChildWorkspace(options)).rejects.toBe(failure);
    const preserved = (await readNativeSupervisorState(paths, 'parent'))!;
    const execution = preserved.integration.checkExecution!;
    expect(execution).toMatchObject({
      status: 'running',
      activeProcess: { status: 'running', checkId: 'pending', pid: 2147483000 },
      checkStates: [
        { id: 'passed', status: 'passed', executionCount: 1 },
        { id: 'pending', status: 'running', executionCount: 1 },
      ],
    });
    await expect(
      integrateNativeSupervisorChildWorkspace({
        ...options,
        state: preserved,
        retryCheckIds: ['pending'],
      }),
    ).rejects.toThrow('already running');

    execution.ownerPid = 2147483001;
    await writeNativeSupervisorState(paths, preserved);
    vi.spyOn(checkExecutor, 'inspectNativeCheckProcessTreeLiveness').mockResolvedValue('unknown');
    await expect(
      integrateNativeSupervisorChildWorkspace({ ...options, state: preserved }),
    ).rejects.toThrow('check process is still running');
    expect((await readNativeSupervisorState(paths, 'parent'))!.integration.checkExecution).toEqual(
      execution,
    );
    expect(execute).toHaveBeenCalledTimes(2);
    const target = (await inspectNativeCheckStopEvidenceTargets(paths, 'parent')).find(
      ({ kind }) => kind === 'supervisor-integration-checks',
    )!;
    expect(target.canConfirm).toBe(true);
    const confirmation = {
      ...target.confirmation,
      evidence:
        'Confirmed the integration check and all descendants stopped using the host process inventory.',
    };
    const recover = (confirmations: unknown = [confirmation]) =>
      recoverNativeChecksWithStopEvidence({ paths, name: 'parent', confirmations });
    await expect(recover([{ ...confirmation, executionHash: '0'.repeat(64) }])).rejects.toThrow(
      '快照已变化',
    );
    expect(await readNativeSupervisorState(paths, 'parent')).toEqual(preserved);
    const originalWrite = atomicFile.atomicWriteJson;
    const failApplied = vi
      .spyOn(atomicFile, 'atomicWriteJson')
      .mockImplementation(async (file, value, settings) => {
        if (
          (value as { schema?: string; applied?: boolean }).schema ===
            'comet.native.check-stop-evidence.v1' &&
          (value as { applied?: boolean }).applied
        )
          throw new Error('applied write failed');
        return originalWrite(file, value, settings);
      });
    await expect(recover()).rejects.toThrow('applied write failed');
    failApplied.mockRestore();
    const recovered = (await readNativeSupervisorState(paths, 'parent'))!;
    expect(recovered.stateVersion).toBe(preserved.stateVersion + 1);
    expect(recovered.integration.checkExecution).toMatchObject({
      status: 'interrupted',
      operationId: execution.operationId,
      activeProcess: null,
      checkStates: [
        { id: 'passed', status: 'passed', executionCount: 1 },
        { id: 'pending', status: 'interrupted', executionCount: 1 },
      ],
    });
    expect(recovered.integration.checkExecution!.checkStates![0]).toEqual(
      execution.checkStates![0],
    );
    await expect(recover()).resolves.toMatchObject({ alreadyApplied: true });
    await expect(recover()).resolves.toMatchObject({ alreadyApplied: true });
    expect(await readNativeSupervisorState(paths, 'parent')).toEqual(recovered);
    expect(execute).toHaveBeenCalledTimes(2);
  });

  it('reserves the integration worktree before running checks with competing plans', async () => {
    const { root, paths, state } = await verifiedSupervisor();
    const marker = path.join(resolveWorkspaceRuntimeRootSync(root), 'integration-started');
    const release = path.join(resolveWorkspaceRuntimeRootSync(root), 'integration-release');
    const first = integrateNativeSupervisorChildWorkspace({
      paths,
      state,
      name: 'core',
      checks: [],
      checkPlans: [
        plan(
          'first',
          "const fs=require('node:fs');fs.writeFileSync(process.argv[1],'started');const timer=setInterval(()=>{if(fs.existsSync(process.argv[2])){clearInterval(timer);process.exit(0)}},20)",
          [marker, release],
        ),
      ],
    });
    // Attach a handler while the competing request is inspected.
    const settled = first.then(
      (value) => ({ value }),
      (error) => ({ error }),
    );
    try {
      await expect
        .poll(
          async () =>
            fs.access(marker).then(
              () => true,
              () => false,
            ),
          { timeout: 10000 },
        )
        .toBe(true);
      await expect(
        integrateNativeSupervisorChildWorkspace({
          paths,
          state,
          name: 'core',
          checks: [],
          checkPlans: [plan('different')],
        }),
      ).rejects.toThrow(/running|state changed/);
      const latest = (await readNativeSupervisorState(paths, 'parent'))!;
      await expect(
        integrateNativeSupervisorChildWorkspace({
          paths,
          state: latest,
          name: 'core',
          checks: [],
          checkPlans: [plan('different')],
        }),
      ).rejects.toThrow(/running/);
      await expect
        .poll(
          async () =>
            (await readNativeSupervisorState(paths, 'parent'))?.integration.checkExecution
              ?.activeProcess?.status,
          { timeout: 10000 },
        )
        .toBe('running');
      const orphaned = (await readNativeSupervisorState(paths, 'parent'))!;
      // A recovered overlay may refer to an exited owner while its real check is alive.
      orphaned.integration.checkExecution!.ownerIdentity = 'previous-owner-instance';
      await fs.writeFile(nativeSupervisorStateFile(paths, 'parent'), JSON.stringify(orphaned));
      await expect(
        integrateNativeSupervisorChildWorkspace({
          paths,
          state: orphaned,
          name: 'core',
          checks: [],
          checkPlans: [plan('orphan-retry')],
        }),
      ).rejects.toThrow('check process is still running');
    } finally {
      await fs.writeFile(release, 'release');
      await settled;
    }
    expect(await settled).toMatchObject({
      value: {
        children: [{ status: 'integrated', checks: [{ name: 'first', status: 'passed' }] }],
      },
    });
  }, 120000);

  it('preserves a failed integration receipt and requires a changed plan before retry', async () => {
    const { paths, state } = await verifiedSupervisor();
    await expect(
      integrateNativeSupervisorChildWorkspace({
        paths,
        state,
        name: 'core',
        checks: [],
        checkPlans: [plan('fails', 'process.exit(1)')],
      }),
    ).rejects.toThrow('did not pass');
    const failed = (await readNativeSupervisorState(paths, 'parent'))!;
    expect(failed.children[0].status).toBe('verified');
    expect(failed.integration.checkExecution).toMatchObject({
      status: 'interrupted',
      activeProcess: null,
      receiptRef: expect.stringContaining('runtime/evidence/reports/'),
      checks: [{ name: 'fails', status: 'failed' }],
    });
    await expect(
      integrateNativeSupervisorChildWorkspace({
        paths,
        state: failed,
        name: 'core',
        checks: [],
        checkPlans: [plan('fails', 'process.exit(1)')],
      }),
    ).rejects.toThrow('already failed on the identical plan');
    expect((await readNativeSupervisorState(paths, 'parent'))!.integration.checkExecution).toEqual(
      failed.integration.checkExecution,
    );
    const completed = await integrateNativeSupervisorChildWorkspace({
      paths,
      state: failed,
      name: 'core',
      checks: [],
      checkPlans: [plan('retry')],
    });
    expect(completed.children[0]).toMatchObject({
      status: 'integrated',
      checks: [{ name: 'retry', status: 'passed' }],
    });
    expect(completed.integration.checkExecution).toMatchObject({
      status: 'completed',
      activeProcess: null,
    });
    expect(completed.integration.checkExecution!.operationId).not.toBe(
      failed.integration.checkExecution!.operationId,
    );
  }, 120000);

  it('exposes only interrupted integration checks as an explicit retry action', async () => {
    const { paths, state } = await verifiedSupervisor();
    await expect(
      integrateNativeSupervisorChildWorkspace({
        paths,
        state,
        name: 'core',
        checks: [],
        checkPlans: [{ ...plan('interrupted', 'setInterval(() => {}, 25)', []), timeoutMs: 5000 }],
      }),
    ).rejects.toThrow('was interrupted');

    const current = (await readNativeSupervisorState(paths, 'parent'))!;
    const portable = await readNativePortableChange(paths, 'parent');
    const children = await inspectNativeChildren({ paths, state: portable });
    const continuation = nativePortableContinuation(portable, children, {
      supervisorIntegrationRetryIds: current.integration.checkExecution?.checkStates
        ?.filter(({ status }) => status === 'interrupted')
        .map(({ id }) => id),
    });
    const template = continuation.inputOptions.find(
      ({ template }) =>
        !Array.isArray(template) && (template as { kind?: string }).kind === 'supervisor-integrate',
    )?.template as { retry_check_ids?: string[] } | undefined;
    expect(template?.retry_check_ids).toEqual(['interrupted']);
  }, 120000);
});

import { spawn, type ChildProcessWithoutNullStreams } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it } from 'vitest';

import { acquireNativeLock, releaseNativeLock } from '../../../domains/comet-native/native-lock.js';
import { nativeProjectPaths } from '../../../domains/comet-native/native-paths.js';
import type { NativeProjectPaths } from '../../../domains/comet-native/native-types.js';

interface WorkerResult {
  code: number | null;
  stdout: string;
  stderr: string;
}

const fixture = fileURLToPath(
  new URL('../../fixtures/native-lock-process-worker.ts', import.meta.url),
);

async function waitFor(file: string): Promise<void> {
  const deadline = Date.now() + 10_000;
  while (Date.now() < deadline) {
    try {
      await fs.access(file);
      return;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
      await new Promise((resolve) => setTimeout(resolve, 5));
    }
  }
  throw new Error(`Timed out waiting for ${file}`);
}

async function waitForText(file: string): Promise<string> {
  const deadline = Date.now() + 10_000;
  while (Date.now() < deadline) {
    try {
      const text = await fs.readFile(file, 'utf8');
      if (text.length > 0) return text;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
    }
    await new Promise((resolve) => setTimeout(resolve, 5));
  }
  throw new Error(`Timed out waiting for content in ${file}`);
}

function collect(child: ChildProcessWithoutNullStreams): Promise<WorkerResult> {
  let stdout = '';
  let stderr = '';
  child.stdout.setEncoding('utf8').on('data', (chunk: string) => (stdout += chunk));
  child.stderr.setEncoding('utf8').on('data', (chunk: string) => (stderr += chunk));
  return new Promise((resolve) => {
    child.once('exit', (code) => resolve({ code, stdout, stderr }));
  });
}

describe('Native lock process concurrency', () => {
  let buildRoot: string;
  let worker: string;
  let projectRoot: string;
  let paths: NativeProjectPaths;

  beforeAll(async () => {
    buildRoot = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-native-lock-worker-'));
    worker = path.join(buildRoot, 'worker.mjs');
    await build({
      entryPoints: [fixture],
      outfile: worker,
      bundle: true,
      platform: 'node',
      format: 'esm',
      target: 'node20',
      banner: {
        js: [
          "import { createRequire as __cometCreateRequire } from 'module';",
          'const require = __cometCreateRequire(import.meta.url);',
        ].join('\n'),
      },
    });
  });

  beforeEach(async () => {
    projectRoot = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-native-lock-process-'));
    paths = await nativeProjectPaths(projectRoot, '.');
    await fs.mkdir(paths.locksDir, { recursive: true });
  });

  afterEach(async () => {
    await fs.rm(projectRoot, { recursive: true, force: true });
  });

  afterAll(async () => {
    await fs.rm(buildRoot, { recursive: true, force: true });
  });

  function startWorker(args: string[]): {
    child: ChildProcessWithoutNullStreams;
    result: Promise<WorkerResult>;
  } {
    const child = spawn(process.execPath, [worker, ...args], {
      cwd: projectRoot,
      stdio: ['pipe', 'pipe', 'pipe'],
    });
    return { child, result: collect(child) };
  }

  it.each(['root-move', 'transition-example'])(
    'allows only one process to replace a diagnosed stale %s lock',
    async (lockName) => {
      const lockFile = path.join(paths.locksDir, `${lockName}.lock`);
      await fs.writeFile(
        lockFile,
        JSON.stringify({
          id: `stale-${lockName}`,
          pid: 2_147_483_647,
          hostname: os.hostname(),
          createdAt: '2026-07-17T00:00:00.000Z',
          operation: 'interrupted operation',
        }),
      );
      const readyPrimary = path.join(projectRoot, 'primary.ready');
      const readyLate = path.join(projectRoot, 'late.ready');
      const go = path.join(projectRoot, 'go');
      const primaryStatus = path.join(projectRoot, 'primary.status');
      const lateStatus = path.join(projectRoot, 'late.status');
      const release = path.join(projectRoot, 'release');
      const primary = startWorker([
        'takeover',
        projectRoot,
        lockName,
        'primary',
        readyPrimary,
        go,
        primaryStatus,
        release,
      ]);
      const late = startWorker([
        'takeover',
        projectRoot,
        lockName,
        'late',
        readyLate,
        go,
        lateStatus,
        release,
      ]);

      await Promise.all([waitFor(readyPrimary), waitFor(readyLate)]);
      await fs.writeFile(go, 'go\n');
      await Promise.all([waitFor(primaryStatus), waitFor(lateStatus)]);
      const statuses = await Promise.all([
        fs.readFile(primaryStatus, 'utf8'),
        fs.readFile(lateStatus, 'utf8'),
      ]);
      expect(statuses.filter((status) => status.startsWith('acquired:'))).toHaveLength(1);
      expect(statuses.filter((status) => status.startsWith('blocked:'))).toHaveLength(1);

      await fs.writeFile(release, 'release\n');
      const results = await Promise.all([primary.result, late.result]);
      expect(results).toEqual([
        expect.objectContaining({ code: 0, stderr: '' }),
        expect.objectContaining({ code: 0, stderr: '' }),
      ]);
      expect(JSON.parse(results[0].stdout)).toMatchObject({ takeover: { status: 'removed' } });
      expect(JSON.parse(results[1].stdout)).toMatchObject({ takeover: { status: 'changed' } });
    },
  );

  it('prevents an old owner release from removing a replacement owner', async () => {
    const old = await acquireNativeLock(paths, 'archive', 'old archive owner');
    const oldSnapshot = path.join(projectRoot, 'old-lock.json');
    await fs.writeFile(oldSnapshot, JSON.stringify(old));
    await releaseNativeLock(old);
    const replacement = await acquireNativeLock(paths, 'archive', 'replacement archive owner');
    const ready = path.join(projectRoot, 'release.ready');
    const go = path.join(projectRoot, 'release.go');
    const status = path.join(projectRoot, 'release.status');
    const workerProcess = startWorker([
      'release-old',
      projectRoot,
      'archive',
      'late',
      ready,
      go,
      status,
      oldSnapshot,
    ]);

    await waitFor(ready);
    await fs.writeFile(`${go}.primary`, 'replacement-ready\n');
    await fs.writeFile(go, 'go\n');
    await expect(waitForText(status)).resolves.toMatch(/^blocked:/u);
    expect(await fs.readFile(replacement.file, 'utf8')).toContain(replacement.owner.id);
    await expect(workerProcess.result).resolves.toMatchObject({ code: 0, stderr: '' });
    await releaseNativeLock(replacement);
  });

  it('elects one winner when two processes acquire the same free lock together', async () => {
    const readyA = path.join(projectRoot, 'race-a.ready');
    const readyB = path.join(projectRoot, 'race-b.ready');
    const go = path.join(projectRoot, 'race.go');
    const statusA = path.join(projectRoot, 'race-a.status');
    const statusB = path.join(projectRoot, 'race-b.status');
    const release = path.join(projectRoot, 'race.release');
    const contenders = [
      startWorker(['acquire-race', projectRoot, 'root-move', 'a', readyA, go, statusA, release]),
      startWorker(['acquire-race', projectRoot, 'root-move', 'b', readyB, go, statusB, release]),
    ];

    await Promise.all([waitFor(readyA), waitFor(readyB)]);
    await fs.writeFile(go, 'go\n');
    const statuses = await Promise.all([waitForText(statusA), waitForText(statusB)]);
    expect(statuses.filter((status) => status.startsWith('acquired:'))).toHaveLength(1);
    expect(statuses.filter((status) => status.startsWith('blocked:'))).toHaveLength(1);
    expect(statuses.join('\n')).not.toContain('coordinator is busy');

    await fs.writeFile(release, 'release\n');
    await expect(Promise.all(contenders.map(({ result }) => result))).resolves.toEqual([
      expect.objectContaining({ code: 0, stderr: '' }),
      expect.objectContaining({ code: 0, stderr: '' }),
    ]);
  });
});

