    const options = {
      projectRoot: root,
      name: run.runId,
      dryRun: false,
      recover: false,
      confirmed: false,
    };
    const finalize = nativeSdkArchiveFinalizeExecutor.execute;
    vi.spyOn(nativeSdkArchiveFinalizeExecutor, 'execute').mockImplementationOnce(
