    });
    expect(moves).toHaveLength(['report', 'report-journal', 'move'].includes(point) ? 1 : 0);
    expect(await fs.readFile(specFile, 'utf8')).toBe(spec);
    expect((await fs.stat(specFile)).mtimeMs).toBe(specStat.mtimeMs);
